"""Reasoning and intermediate magnitudes for the thirty existing cases."""
ROUTES={}
def route(key,strategy,steps):ROUTES[key]=dict(strategy=strategy,steps=[dict(target=k,expression=e,unit=u,why=w) for k,e,u,w in steps])
route('P01',r'Combinar $dp/dH=-\rho g$ con $\rho=p/(RT)$ y $T=T_b-\beta H$ da $dp/p=-g\,dH/[R(T_b-\beta H)]$. Integrar desde la base fija la constante y produce $\ln(p/p_b)=[g/(R\beta)]\ln(T/T_b)$.', [('T','Tb-beta*H','K','Obtener primero la temperatura del nivel.'),('a','g/(R*beta)','','El exponente es adimensional.'),('p','pb*(T/Tb)**a','Pa','Exponenciar la relación integrada.')])
route('P02',r'La misma integración hidrostática da $p=p_b(T/T_b)^{g/(R\beta)}$. Después se usa la ecuación de estado con temperatura local, no la de la base.', [('T','Tb-beta*H','K','Calcular la temperatura sin redondeo previo.'),('p','pb*(T/Tb)**(g/(R*beta))','Pa','Calcular la presión de la capa.'),('rho','p/(R*T)','kg/m**3','Dividir presión por constante y temperatura absoluta.')])
route('P03',r'En una capa isoterma $T=T_b$, separar hidrostática da $dp/p=-g\,dH/(RT_b)$. Integrar entre la base y el nivel da $p=p_be^{-g\Delta H/(RT_b)}$.', [('exponent','-g*dH/(R*Tb)','','El exponente negativo debe ser adimensional.'),('p','pb*exp(exponent)','Pa','Usar la presión de base de 11 km, no la del mar.')])
route('P04',r'Igualar $g_0H$ al incremento de potencial del campo esférico da $H=R_ez/(R_e+z)$. La altura geométrica entra tanto en numerador como denominador.', [('factor','Rearth/(Rearth+z)','','Calcular el factor menor que uno.'),('H','factor*z','m','Multiplicar por altura geométrica.')])
route('P05',r'En la troposfera $\rho/\rho_0=(1-\beta H/T_b)^a$ con $a=g/(R\beta)-1$. Elevar ambos lados a $1/a$, pasar términos y dividir por $\beta/T_b$ permite despejar altura.', [('a','g/(R*beta)-1','','Identificar el exponente de densidad, diferente del de presión.'),('f','(rho/rho0)**(1/a)','','Tomar la potencia inversa del cociente de densidades.'),('H','Tb/beta*(1-f)','m','Aislar la altura geopotencial.')])
route('P06',r'El sonido adiabático de gas ideal caloríficamente perfecto cumple $a^2=\gamma RT$. Primero obtener su raíz positiva y después dividir la velocidad verdadera por ella.', [('a','sqrt(gamma*R*T)','m/s','Usar temperatura estática en kelvin.'),('M','V/a','','Mach es un cociente de velocidades.')])
route('P07',r'La geometría de la envolvente acústica da $\sin\mu=1/M$. Como el dato es supersónico, el argumento está entre cero y uno y se toma el ángulo agudo.', [('s','1/Ma','','Comprobar el argumento del arco seno.'),('mu','asin(s)*180/pi','degree','Convertir el ángulo de radianes a grados.')])
route('P08',r'De $\mathrm{Re}=\rho Vc/\mu$, multiplicar por viscosidad y dividir por densidad y velocidad para aislar la cuerda.', [('c','Re*mu/(rho*V)','m','Conservar unidades SI antes de dividir.')])
route('P09',r'El balance estacionario sin fugas conserva caudal másico: $\dot m=\rho_1A_1V_1=\rho_2A_2V_2$. Calcular el caudal entrante y despejar densidad de salida; no conservar solo $AV$.', [('mdot','rho1*A1*V1','kg/s','Integrar el flujo de masa uniforme en la entrada.'),('rho2','mdot/(A2*V2)','kg/m**3','Dividir por caudal volumétrico de salida.')])
route('P10',r'Bernoulli horizontal sin máquinas ni pérdidas da $\Delta p=\rho(V_2^2-V_1^2)/2$. Multiplicar por $2/\rho$ y sumar $V_1^2$ antes de tomar raíz.', [('V2sq','V1**2+2*dp/rho','m**2/s**2','Aislar el cuadrado de la velocidad final.'),('V2','sqrt(V2sq)','m/s','Escoger la raíz positiva para la celeridad.')])
route('P11',r'En el modelo Pitot incompresible ideal, $q_c=\rho V^2/2$. No se conoce por ello la temperatura: el Mach no puede obtenerse solo de estos datos.', [('V','sqrt(2*qc/rho)','m/s','Despejar la velocidad positiva de la diferencia de presión.')])
route('P12',r'Partir de $p_t/p=[1+(\gamma-1)M^2/2]^{\gamma/(\gamma-1)}$. Elevar a $(\gamma-1)/\gamma$, restar uno y multiplicar por $2/(\gamma-1)$ aísla $M^2$.', [('ratio','pt/p','','Formar cociente de presiones absolutas.'),('M2','2/(gamma-1)*(ratio**((gamma-1)/gamma)-1)','','Aplicar potencia inversa y despejar el cuadrado.'),('M','sqrt(M2)','','Tomar la raíz positiva y comprobar rama subsónica.')])
route('P13',r'Arquímedes da empuje $\rho_{aire}Vg$. En equilibrio compensa peso de gas, estructura y carga: $\rho_{aire}V=\rho_{gas}V+m_s+m_c$. Cancelar gravedad y despejar carga.', [('mnet','(rhoair-rhogas)*Vol','kg','Restar masa de helio a masa de aire desplazada.'),('mc','mnet-ms','kg','Restar masa estructural, sin volver a restar helio.')])
route('P14',r'La cuerda varía linealmente desde $c_r$ a $c_t=\lambda c_r$ a lo largo de cada semiala. Integrar esa recta equivale a envergadura completa por cuerda media aritmética.', [('ct','lam*cr','m','Calcular cuerda de punta.'),('S','b*(cr+ct)/2','m**2','Sumar el área de los dos trapecios semialares.')])
route('P15',r'La CAM se define como $\bar c=(1/S)\int_{-b/2}^{b/2}c(y)^2dy$. Para cuerda lineal, integrar el cuadrado y dividir por $S=b(c_r+c_t)/2$ da $\bar c=(2c_r/3)(1+\lambda+\lambda^2)/(1+\lambda)$.', [('num','1+lam+lam**2','','Evaluar la combinación cuadrática de estrechamiento.'),('cam','2*cr/3*num/(1+lam)','m','Multiplicar por la cuerda raíz y dividir por el factor de área.')])
route('P16',r'El perfil responde al ángulo efectivo: $C_L=a_0[\alpha-\alpha_0-C_L/(\pi e_i AR)]$. Agrupar términos en $C_L$ da $C_L[1+a_0/(\pi e_i AR)]=a_0(\alpha-\alpha_0)$, de donde se lee la pendiente del ala.', [('factor','1+a0/(pi*ei*AR)','','La corrección por ángulo inducido aumenta el denominador.'),('a','a0/factor','','La pendiente se interpreta por radián.')])
route('P17',r'Igualar el coeficiente cuadrático total $K=1/(\pi e_iAR)+k_p$ con $1/(\pi e_OAR)$. Multiplicar por $\pi AR$ y tomar el recíproco aísla $e_O$.', [('inv','1/ei+pi*AR*kp','','Sumar ambas contribuciones antes de invertir.'),('eO','1/inv','','El resultado tiende a eficiencia inducida cuando el término de perfil se anula.')])
route('P18',r'En vuelo horizontal uniforme, $L=W$. Usar $L=qSC_L$ y $q=\rho V^2/2$ y despejar el coeficiente.', [('q','rho*V**2/2','Pa','Calcular presión dinámica de la condición.'),('CL','W/(q*S)','','Dividir peso por fuerza de referencia.')])
route('P19',r'El equilibrio tangencial exige $T=D$. Con la polar $D=qS(C_{D0}+KC_L^2)$ y $C_L=W/(qS)$, calcular sustentación, coeficiente de resistencia y fuerza en ese orden.', [('q','rho*V**2/2','Pa','Formar presión dinámica.'),('CL','W/(q*S)','','Imponer equilibrio vertical.'),('CD','CD0+K*CL**2','','Evaluar la polar en el coeficiente requerido.'),('T','q*S*CD','N','Imponer equilibrio tangencial.')])
route('P20',r'Escribir $D=AV^2+B/V^2$, con $A=\rho SC_{D0}/2$ y $B=2KW^2/(\rho S)$. Derivar da $2AV-2B/V^3=0$, luego $V^4=B/A$; la segunda derivada es positiva.', [('A','rho*S*CD0/2','kg/m','Identificar el término cuadrático de resistencia.'),('B','2*K*W**2/(rho*S)','N*m**2/s**2','Identificar el término inversamente cuadrático.'),('Vopt','(B/A)**.25','m/s','Tomar la cuarta raíz positiva.')])
route('P21',r'La potencia necesaria es $P=DV=AV^3+B/V$. Su derivada $3AV^2-B/V^2=0$ da $V^4=B/(3A)$. No se usa el óptimo de resistencia sin modificarlo.', [('A','rho*S*CD0/2','kg/m','Conservar el coeficiente parásito.'),('B','2*K*W**2/(rho*S)','N*m**2/s**2','Conservar el término de sustentación.'),('Vopt','(B/(3*A))**.25','m/s','Tomar la cuarta raíz del cociente con factor tres.')])
route('P22',r'Derivar $E=C_L/(C_{D0}+KC_L^2)$ da numerador $C_{D0}-KC_L^2$. El óptimo positivo cumple $KC_L^2=C_{D0}$ y el denominador se convierte en $2C_{D0}$.', [('CLopt','sqrt(CD0/K)','','Despejar el coeficiente óptimo.'),('Emax','CLopt/(2*CD0)','','Evaluar la eficiencia con el óptimo.')])
route('P23',r'En ascenso rectilíneo uniforme, $T-D=W\sin\gamma$. La componente vertical de velocidad es $V\sin\gamma$. Sustituir el equilibrio produce $ROC=(T-D)V/W$.', [('s','(T-D)/W','','Comprobar que el seno sea físicamente posible.'),('ROC','V*s','m/s','La potencia excedente se convierte en ganancia de altura.')])
route('P24',r'En planeo estabilizado, $\tan|\gamma|=D/L$. En el triángulo de la trayectoria, altura/alcance horizontal tiene ese mismo cociente. Despejar alcance da $R=hL/D$.', [('R','height*LD','m','Multiplicar la altura disponible por la eficiencia impuesta.')])
route('P25',r'En viraje horizontal coordinado, $L\cos\phi=W$ y $L\sin\phi=mV^2/r$. Dividir ambas elimina $L$ y da $\tan\phi=V^2/(rg)$, que se despeja para el radio.', [('acc','g*tan(phi)','m/s**2','Obtener aceleración centrípeta de la inclinación.'),('r','V**2/acc','m','Dividir velocidad al cuadrado por aceleración.')])
route('P26',r'Las posiciones se expresan desde el mismo origen y en unidades de CAM. El margen estático es la distancia del CG al punto neutro, positiva si este queda detrás.', [('SM','hn-hcg','','Restar posiciones conservando el orden y el signo.')])
route('P27',r'Para mantener derrota, la componente transversal de velocidad aérea debe cancelar al viento: $V\sin\chi_c=|V_{w,\perp}|$. Se despeja el ángulo agudo y el morro apunta hacia el lado de procedencia del viento.', [('s','cross/V','','Comprobar que el viento transversal no exceda la TAS.'),('angle','asin(s)*180/pi','degree','Aplicar arco seno y convertir a grados.')])
route('P28',r'En órbita circular de dos cuerpos, la aceleración gravitatoria $\mu/r^2$ iguala la centrípeta $V^2/r$. Multiplicar por $r$ y tomar raíz positiva da $V=\sqrt{\mu/r}$.', [('V','sqrt(mu/r)','m/s','Usar radio al centro, no altitud sobre la superficie.')])
route('P29',r'La conservación de momento de una etapa ideal da $dv=-c\,dm/m$, con $c=I_{sp}g_0$. Integrar entre masas inicial y final da $\Delta v=c\ln(m_i/m_f)$.', [('c','Isp*g','m/s','Convertir impulso específico a velocidad efectiva.'),('dv','c*log(ratio)','m/s','Usar logaritmo natural de la razón de masas.')])
route('P30',r'La potencia hidráulica útil es trabajo por volumen $\Delta p$ por caudal $Q$. El rendimiento se define como $\eta=P_u/P_{entrada}$; despejar entrada implica dividir, no multiplicar, por el rendimiento.', [('Pu','dp*Q','W','Calcular potencia útil transferida al líquido.'),('Pin','Pu/eta','W','Obtener la demanda de entrada, mayor que la útil.')])
